insert into public.providers (id, user_id, category_id, legacy_id, business_name, short_description, description, city, area, address, instagram_url, website, logo_url, cover_image_url, capacity, price_from, price_to, currency, price_note, status, source, source_ref) values
  ('a84cb1ac-960d-5ce1-a692-aace78ac81b4', null, 'halls', 'hall_ritaj_001', 'قاعة الريتاج للمناسبات', 'قاعة مناسبات في المدينة المائية تقدّم عروضاً شاملة للأعراس والحفلات.', 'قاعة للأعراس والحفلات والمناسبات في المدينة المائية مقابل حي الجامع. عرضها الحالي يشمل مصورة محترفة، ملاية/قارئة، موظفات تفتيش وتنظيم، وزفة موسيقى وطلة عروس.', 'بغداد', 'المدينة المائية', 'المدينة المائية — مقابل حي الجامع', 'https://www.instagram.com/ritajhall', null, null, null, null, null, null, 'IQD', null, 'published', 'pdf', 'قاعة الريتاج للمناسبات.pdf'),
  ('9c2b77e6-1649-5abd-86ea-9257a6a99e03', null, 'halls', 'hall_rotana_baghdad_001', 'مطعم وقاعة روتانا بغداد', 'قاعة أفراح في الوزيرية مع ديجي وتصوير وفرقة وكيكة ضمن الحجز.', 'مطعم وقاعة في الوزيرية قرب جامعة بغداد لإقامة الحفلات والمناسبات. تتضمن فقرات مجانية مع الحجز مثل الديجي والتصوير الفوتوغرافي والفيديو وكيكة العرسان وميز عقد المهر والحناء وفرقة بصراوية وكراج مجاني.', 'بغداد', 'الوزيرية', 'الوزيرية — قرب جامعة بغداد', 'https://www.instagram.com/rotana_baghdad_', null, null, null, null, 750000, 1000000, 'IQD', 'أسعار حجز القاعة حسب المصدر: الأيام العادية 750,000 · نهاية الأسبوع 1,000,000', 'published', 'pdf', 'عرض حجز قاعة روتانا بغداد.pdf'),
  ('1b7ea7e7-1973-5710-a9df-ce89163493ee', null, 'halls', 'hall_malika_001', 'قاعة الملكة للمناسبات', 'قاعة في زيونة بعرضين نهاري ومسائي وكوشة ملكية وكادر نسائي.', 'قاعة مناسبات في زيونة، شارع الربيعي مجاور أمير مول. تقدّم عرضين (فترة نهارية وفترة مسائية)، ومع العرضين خدمات مجانية منها كوشة ملكية فخمة، تصوير فيديو وصور ومونتاج، ليزر وإضاءة حديثة، كادر نسائي متكامل، وكيكة المناسبة 3 طوابق.', 'بغداد', 'زيونة', 'زيونة — شارع الربيعي — مجاور أمير مول', 'https://www.instagram.com/queen__6h', null, null, 'assets/images/providers/hall_malika/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'عروض_قاعة_الملكة_للمناسبات_مع_الصور.pdf'),
  ('a34038e2-5362-5385-89e8-988510173fa6', null, 'halls', 'hall_weam_001', 'سلسلة قاعات الحاج وئام السوداني', 'سلسلة قاعات ومطاعم للأعراس والمؤتمرات في العامرية والقادسية والمنصور.', 'سلسلة قاعات للأعراس والمؤتمرات والاحتفالات. تضم: قاعة ليفانسيا LEVANSIA (العامرية)، قاعة ليفانت وإيليجانت (القادسية)، قاعة وحدائق زيوس الملكية (المنصور)، قاعة أوبال الملكية، ومطعم كرم بغدادي.', 'بغداد', 'العامرية · القادسية · المنصور', null, 'https://www.instagram.com/weam_alsudany', null, null, 'assets/images/providers/hall_weam/02.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'سلسلة قاعات الحاج وئام السوداني.pdf'),
  ('d356023e-18eb-5619-be94-e9150e9817b8', null, 'halls', 'hall_asawer_001', 'قاعة أساور اللؤلؤ الملكية', 'قاعة للمناسبات والاحتفالات الفاخرة في المنصور مع فرع في الكرادة.', 'قاعة للمناسبات والاحتفالات الفاخرة في المنصور، شارع أبو جعفر المنصور (بناية حلويات الحاج مهدي الخاصكي)، وفرع آخر في الكرادة شارع 62. أقسامها: سنتر بيس القاعة والديكورات الحديثة، تجهيز الكوشات والممرات، وقسم الضيافة والحلويات الخاصة.', 'بغداد', 'المنصور · الكرادة', 'المنصور — شارع أبو جعفر المنصور، بناية حلويات الحاج مهدي الخاصكي · فرع الكرادة — شارع 62', 'https://www.instagram.com/asawer_al_loaloa', null, null, 'assets/images/providers/hall_asawer/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'قاعة أساور اللؤلؤ الملكية.pdf'),
  ('bbd09e25-fba8-587b-9dce-8eed35e93e60', null, 'halls', 'hall_jadriya_001', 'مطعم وحدائق الجادرية — قاعة الخاتون', 'قاعة الخاتون في الجادرية: تتسع لـ200 شخص وحفلة لمدة 5 ساعات.', 'قاعة الخاتون ضمن مطعم وحدائق الجادرية، تتسع لـ200 شخص براحة تامة، طابق أرضي مريح بدون أعمدة، وقت الحفلة 5 ساعات، مع كراج سيارات خاص. تتوفر خدمات نسائية متخصصة (كادر خدمة نسائي، دي جي نسائي، تصوير نسائي) وقائمة أطباق طعام بأسعار من 7,000 إلى 18,000 دينار للطبق.', 'بغداد', 'الجادرية', 'بغداد — الجادرية — تقاطع جامعة بغداد', 'https://www.instagram.com/aljadriya_restaurant', null, null, null, 200, null, null, 'IQD', null, 'published', 'pdf', 'مطعم_وحدائق_الجادرية_قاعة_الخاتون.pdf'),
  ('2f70d4c9-71c2-5e7c-b62e-41df7316dda9', null, 'photography', 'photo_tabarek_001', 'تبارك صلاح', 'تصوير أعراس ومناسبات وجلسات خارجية وألبومات فاخرة في بغداد.', 'Tabarek Salah Photography — توثيق أهم اللحظات: تغطية كاملة وشاملة للأفراح والمناسبات الداخلية، جلسات تصوير خارجية في أجمل الأماكن ببغداد، وتصميم ألبومات فاخرة ومخصصة.', 'بغداد', null, null, null, null, null, 'assets/images/providers/photo_tabarek/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج خدمات التصوير - تبارك صلاح.pdf'),
  ('1ce420d8-9cb7-502a-a3cb-b116a8b9ae69', null, 'photography', 'photo_shot_001', 'لقطة زفاف — Shot Wedding', 'تصوير أعراس بلمسات سينمائية كلاسيكية وجلسات خارجية تراثية.', 'مصور فوتوغرافي محترف لتغطيات الأعراس بأسلوب فني راقٍ ولمسات سينمائية كلاسيكية، مع تميّز في التصوير الخارجي والتوثيق المعماري ذي الطابع التراثي. مناطق الخدمة حسب المصدر: العراق (بغداد، أربيل، كركوك) وتركيا (إسطنبول).', 'بغداد', 'بغداد · أربيل · كركوك · إسطنبول', null, 'https://www.instagram.com/shot__wedding', null, null, 'assets/images/providers/photo_shot/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج خدمات لقطة زفاف - Shot Wedding.pdf'),
  ('fa730b45-0f59-5cf9-abae-310e5c6f2cf9', null, 'photography', 'photo_asmer_001', 'اسمر — المصور بغداد', 'تصوير زفاف وجلسات خارجية وتخرّج وضباط ومناسبات خاصة في بغداد.', 'مصور فوتوغرافي في بغداد لحفلات الزفاف والجلسات الخارجية وتفاصيل الذكرى. خدمات أخرى حسب المصدر: تخرّج، ضباط، خطوبة، أعياد ميلاد، جلسات موديل وحفلات خاصة. يعتمد معدات تصوير سينمائية وكاميرات احترافية حديثة، وتعديل ألوان وإضاءة معالج تقنياً.', 'بغداد', null, null, 'https://www.instagram.com/photographer__asmer', null, null, 'assets/images/providers/photo_asmer/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج_خدمات_المصور_اسمر_مصور_بغداد.pdf'),
  ('15e9f4f7-b324-54f6-ba37-3c9cb17a4f20', null, 'photography', 'photo_mariam_001', 'مريم الخفاجي', 'تصوير زفاف وبورتريه العروس وجلسات عقد المحكمة.', 'Maream Alkafaji — تهتم بإبراز أدق تفاصيل الجمال والأناقة في يوم الزفاف: لقطات العروس الخاصة، تفاصيل الفستان، والجلسات الثنائية. الحجز والاستفسار برسالة واتساب.', 'بغداد', null, null, 'https://www.instagram.com/maream.alkafaji.ph', null, null, 'assets/images/providers/photo_mariam/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج_خدمات_المصورة_مريم_الخفاجي.pdf'),
  ('aef3ac25-235d-5ea4-8e7e-718d4c5e8cd5', null, 'photography', 'photo_marwa_001', 'ستوديو مروه الطائي', 'موثّقة السعادة — تصوير الأعراس والمناسبات بمعدات Canon وإضاءة Godox.', 'Marwa Altaie — ستوديو لتصوير كافة المناسبات في ساحة الاحتفالات. يستخدم أحدث الكاميرات والإضاءات الاحترافية (Canon R Series & Godox Lighting).', 'بغداد', 'ساحة الاحتفالات', 'ساحة الاحتفالات — ستوديو مروه الطائي', 'https://www.instagram.com/marwa.altaie63', null, null, 'assets/images/providers/photo_marwa/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج_خدمات_ستوديو_مروه_الطائي_موثقة_السعادة.pdf'),
  ('9302cdf3-e1e6-5cd1-b5eb-a764506a7aab', null, 'flowers', 'decor_laflamme_001', 'زهور وهدايا لافلام — LaFlamme Flowers', 'ورد طبيعي فاخر وصناعي وبوكسات هدايا في الجادرية.', 'زهور وهدايا لافلام في الجادرية داخل مطعم لافلام: ورد طبيعي فاخر، ورد صناعي دائم، بوكسات وهدايا مميزة، وهدايا عيد الحب والمناسبات. طرق الدفع: ماستر كارد وزين كاش.', 'بغداد', 'الجادرية', 'الجادرية — داخل مطعم لافلام', 'https://www.instagram.com/laflamme.flowers', null, null, 'assets/images/providers/flowers_laflamme/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج خدمات وعروض LaFlamme Flowers.pdf'),
  ('1d95d03f-b6a2-59a5-8d51-f48629338495', null, 'flowers', 'decor_lucci_001', 'Luccè Flowers', 'مسكات أعراس فاخرة وبوكيهات ورد طبيعي وصناعي في المنصور.', 'Luccè Flowers في المنصور — شارع مول بابيلون باتجاه 14 رمضان: مسكات أعراس فاخرة، مسكات وتنسيقات تخرّج، بوكيهات ورد طبيعي وبوكيهات ورد صناعي. يتوفر دفع إلكتروني.', 'بغداد', 'المنصور', 'المنصور — شارع مول بابيلون، باتجاه 14 رمضان', 'https://www.instagram.com/lucci.flowers2', null, null, 'assets/images/providers/flowers_lucci/01.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'كتالوج خدمات وعروض Lucce Flowers (1).pdf'),
  ('e35a2444-42f3-5dc0-9f5a-db80a1d738d5', null, 'flowers', 'decor_fayrouz_001', 'زهور فيروز — Fayrouz Flowers', 'ورد طبيعي وصناعي وكيك مناسبات وتنسيق هدايا في الكرادة.', 'زهور فيروز في الكرادة شارع 52 (مجاور مطعم بافلو): ورد طبيعي، ورد صناعي، كيك مناسبات، وتنسيق هدايا وتنسيقات حسب الطلب. طرق الدفع: ماستر كارد أو زين كاش. الطلب مباشرة عبر إنستغرام أو واتساب.', 'بغداد', 'الكرادة', 'الكرادة — شارع 52 (مجاور مطعم بافلو)', 'https://www.instagram.com/fayrouz_flowers', null, null, 'assets/images/providers/flowers_fayrouz/02.jpg', null, null, null, 'IQD', null, 'published', 'pdf', 'زهور_فيروز_كتالوج_الباقات_والهدايا.pdf'),
  ('1c341258-dd12-5c37-920a-0dd187a63de3', null, 'flowers', 'decor_ward_001', 'ورد بغداد للزهور الطبيعية', 'باقات بيبي روز وورد طبيعي مع توصيل سريع داخل بغداد.', 'Ward Baghdad — ورد طبيعي وتنسيقات مميزة مع توصيل سريع داخل بغداد. الطلب والحجز عبر مراسلة الصفحة مباشرة. قائمة أسعار تقديرية لباقات البيبي روز حسب العدد.', 'بغداد', 'توصيل داخل بغداد', null, null, null, null, 'assets/images/providers/flowers_ward/01.jpg', null, 10000, 65000, 'IQD', 'أسعار تقديرية لباقات البيبي روز (15 إلى 150 وردة) حسب المصدر', 'published', 'pdf', 'كتالوج ورد بغداد للزهور الطبيعية.pdf'),
  ('e879b3cf-dee2-55f8-aafe-9215c0bb2a66', null, 'halls', 'hall_almas_001', 'قاعة الماس للمناسبات', 'قاعة في الأمين تتسع لـ200 شخص بثلاثة عروض للمناسبات والأفراح.', 'قاعة الماس للمناسبات في الأمين — مدخل إعدادية الجمهورية — فوق ماركت بسكويته. تتسع لـ200 نفر. كافة العروض تشمل مجاناً: دي جي احترافي، تصوير الحفل باحترافية 4K، 30 لقطة مطبوعة، دخان وليزريات حديثة، كوشة VIP فخمة، دخولية مميزة، فرقة بصراوية رجالية، شاشات عرض داخلية، بارك للسيارات، وخدمات أخرى حسب الطلب.', 'بغداد', 'الأمين', 'الأمين — مدخل إعدادية الجمهورية — فوق ماركت بسكويته', null, null, null, null, 200, null, null, 'IQD', null, 'draft', 'pdf', 'عروض قاعة الماس للمناسبات.pdf'),
  ('3aaf0cb8-f58d-5cb0-9bf7-431b00f8ae87', null, 'halls', 'hall_qasr_rotana_001', 'قاعة قصر روتانا', 'قاعة داخل منتزه ألف ليلة وليلة في الأعظمية بعرض شامل.', 'أول قاعة للمناسبات داخل القصر الرئاسي — منتزه ألف ليلة وليلة، الأعظمية. العرض الأساسي: الأرضية المجهزة بالكامل (عدا يوم الجمعة)، الكوشة الملكية مع تزيين الطاولات، نظام الدي جي والإنارة الاحترافية، عروض الليزريات والمؤثرات الضوئية والدخان، مع تصوير وتغطية سينمائية.', 'بغداد', 'الأعظمية', 'الأعظمية — داخل منتزه ألف ليلة وليلة', null, null, null, 'assets/images/providers/hall_qasr_rotana/01.jpg', null, null, null, 'IQD', null, 'draft', 'pdf', 'عرض قاعة قصر روتانا.pdf')
