  ('0b8cf414-8f2a-540f-9f27-5515b24b5a9c', 'a84cb1ac-960d-5ce1-a692-aace78ac81b4', 'العرض الشامل — عرض شهري 9 و10', 'يشمل: مصورة محترفة، ملاية/قارئة، موظفات تفتيش وتنظيم، زفة موسيقى وطلة عروس.', 500000, null, 'IQD', 'عرض خاص لشهري 9 و10 كما ورد في المصدر (السنة غير محددة). الحجز بالمراسلة على الخاص أو واتساب.', true, null, null, 'قاعة الريتاج للمناسبات.pdf', true, 0),
  ('4cbb1a3c-d703-5711-b56f-ff7f621aa2fa', '9c2b77e6-1649-5abd-86ea-9257a6a99e03', 'حجز القاعة — الأيام العادية', null, 750000, null, 'IQD', 'من الأحد إلى الأربعاء.', false, null, null, 'عرض حجز قاعة روتانا بغداد.pdf', true, 0),
  ('750bf2b3-5d14-5388-9122-c17b8bc4b220', '9c2b77e6-1649-5abd-86ea-9257a6a99e03', 'حجز القاعة — نهاية الأسبوع', null, 1000000, null, 'IQD', 'الخميس، الجمعة، السبت.', false, null, null, 'عرض حجز قاعة روتانا بغداد.pdf', true, 1),
  ('203d130c-4895-5423-a289-4219444f0756', '1b7ea7e7-1973-5710-a9df-ce89163493ee', 'العرض الأول — الفترة النهارية', 'من 1:00 ظهراً إلى 5:00 عصراً. يشمل 100 قطعة كيك فاخر ومشروبات ببسي باردة.', 750000, null, 'IQD', 'سحب التلفون غير مشمول مع العرض.', true, null, null, 'عروض_قاعة_الملكة_للمناسبات_مع_الصور.pdf', true, 0),
  ('e69acad9-52a6-5e0c-ab5c-9821a7e34f0e', '1b7ea7e7-1973-5710-a9df-ce89163493ee', 'العرض الثاني — الفترة المسائية', 'من 6:00 مساءً إلى 10:00 مساءً. يشمل 100 طبق طعام متكامل.', 1300000, null, 'IQD', 'بدون طعام: 1,000,000 دينار. جلب الطعام من الخارج: أجور خدمة 150,000 دينار. سحب التلفون غير مشمول.', true, null, null, 'عروض_قاعة_الملكة_للمناسبات_مع_الصور.pdf', true, 1),
  ('e25131fa-31ff-5788-8c55-87fd3a62c938', 'd356023e-18eb-5619-be94-e9150e9817b8', 'عرض بمناسبة العيد', 'عرض للحجز فقط.', 1350000, null, 'IQD', 'عرض مؤقت بمناسبة العيد كما ورد في المصدر.', true, null, null, 'قاعة أساور اللؤلؤ الملكية.pdf', true, 0),
  ('0025ff0a-857f-559c-a0c8-66e75284c39b', 'bbd09e25-fba8-587b-9dce-8eed35e93e60', 'العرض الشامل للخدمات والتجهيزات', 'أرضية قاعة + كوشة ملكية، تصوير فوتو مع 50 لقطة طبع بألبوم، شاشة عرض داتاشو، خدمة القاعة الكاملة، دي جي + تصوير فيديو طول الحفلة، إنارة ليزرية + فقاعات + دخان، قالب كيك فوم + سنتر بيس طاولات.', 1500000, null, 'IQD', 'الطعام غير مشمول — الأطباق من 7,000 إلى 18,000 دينار للطبق.', false, null, null, 'مطعم_وحدائق_الجادرية_قاعة_الخاتون.pdf', true, 0),
  ('d4719252-4f6d-5227-992f-a3aebc46d008', '2f70d4c9-71c2-5e7c-b62e-41df7316dda9', 'باقة العرسان الأساسية', 'تغطية مراسم حفل الزفاف داخل القاعة أو المنزل + صور بورتريه للعروسين.', null, null, 'IQD', 'تسليم نسخة رقمية عالية الدقة.', false, null, null, 'كتالوج خدمات التصوير - تبارك صلاح.pdf', true, 0),
  ('cadf8e25-612e-53b4-b498-2b6b154cd7d5', '2f70d4c9-71c2-5e7c-b62e-41df7316dda9', 'باقة الجلسات الخاصة', 'جلسة تصوير خارجية لمدة ساعتين في موقع اختيار العميل ببغداد.', null, null, 'IQD', 'تشمل تعديل واختيار أفضل الصور.', false, null, null, 'كتالوج خدمات التصوير - تبارك صلاح.pdf', true, 1),
  ('a128d84c-33cf-5f53-8ba2-2c2bba1160fd', '2f70d4c9-71c2-5e7c-b62e-41df7316dda9', 'باقة الألبومات الفاخرة', 'ألبوم كبير مغلف بتصميم عصري راقٍ + بوستر هدية للذكرى.', null, null, 'IQD', 'تنسيق خاص حسب الطلب.', false, null, null, 'كتالوج خدمات التصوير - تبارك صلاح.pdf', true, 2),
  ('368be2b8-2115-5f1e-a76c-460db0d5bf0d', '1ce420d8-9cb7-502a-a3cb-b116a8b9ae69', 'باقة الزفاف الكاملة (Wedding Package)', 'تغطية شاملة للحفل والجلسة الخارجية وتجهيزات العروسين؛ تصوير فوتوغرافي وفيديو سينمائي بدقة عالية؛ ألبوم حراري كلاسيكي مصمم خصيصاً؛ تعديل ومعالجة ألوان سينمائية لجميع الصور.', null, null, 'IQD', null, false, null, null, 'كتالوج خدمات لقطة زفاف - Shot Wedding.pdf', true, 0),
  ('2794778e-992a-5a6a-94b3-70a808c4c7a1', '1ce420d8-9cb7-502a-a3cb-b116a8b9ae69', 'باقة الحفلات والجلسات (Bridal & Engagement)', 'تغطية جلسات Bridal Shower وحفلات الحنة؛ تصوير مقاطع Reels قصيرة؛ جلسات خارجية في مواقع مختارة (بغداد / أربيل / إسطنبول)؛ تسليم كادر الصور كاملاً على Drive وبأعلى دقة.', null, null, 'IQD', null, false, null, null, 'كتالوج خدمات لقطة زفاف - Shot Wedding.pdf', true, 1),
  ('d72e292e-529b-59ff-9f3c-8b6b488ac6b7', '15e9f4f7-b324-54f6-ba37-3c9cb17a4f20', 'جلسات عقد المحكمة', 'تغطية كاملة لمراسم عقد المحكمة؛ تصوير فيديو احترافي قصير (Reels)؛ تعديل جميع الصور بأعلى جودة؛ تسليم كادر الصور بملف إلكتروني عالي الدقة.', null, null, 'IQD', null, false, null, null, 'كتالوج_خدمات_المصورة_مريم_الخفاجي.pdf', true, 0),
  ('e7e88a52-268b-50f0-962d-8ce7e34da307', '15e9f4f7-b324-54f6-ba37-3c9cb17a4f20', 'باقة الزفاف الملكية', 'تصوير الجلسة الخارجية واستوديو؛ ألبوم حراري فاخر بطباعة ممتازة؛ لوحة جدارية قياس كبير؛ تغطية تفاصيل العروس (المكياج، الفستان، المجوهرات).', null, null, 'IQD', null, false, null, null, 'كتالوج_خدمات_المصورة_مريم_الخفاجي.pdf', true, 1),
  ('021fd2fa-987b-5226-b057-a939aef7412b', 'aef3ac25-235d-5ea4-8e7e-718d4c5e8cd5', 'باقة الأعراس والزفاف', 'تغطية كاملة للحفل والجلسة الخارجية؛ تصوير فيديو سينمائي + مقاطع Reels؛ ألبوم حراري فاخر بطباعة ممتازة؛ معالجة وألوان احترافية لجميع الصور.', null, null, 'IQD', null, false, null, null, 'كتالوج_خدمات_ستوديو_مروه_الطائي_موثقة_السعادة.pdf', true, 0),
  ('7fc2bc13-1610-5980-b19e-cc66a0f8c38f', 'aef3ac25-235d-5ea4-8e7e-718d4c5e8cd5', 'الحفلات والمناسبات الخاصة', 'جلسات خطوبة وعقد محكمة؛ تصوير حفلات التخرج وأعياد الميلاد؛ تجهيز إضاءة استوديو متكاملة في الموقع؛ تسليم كادر الصور بملف إلكتروني عالي الدقة.', null, null, 'IQD', null, false, null, null, 'كتالوج_خدمات_ستوديو_مروه_الطائي_موثقة_السعادة.pdf', true, 1),
  ('3b8b86be-3b44-523a-a577-fdabddd5def8', '1c341258-dd12-5c37-920a-0dd187a63de3', '15 وردة بيبي روز', 'شامل التغليف الفاخر والكرت.', 10000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 0),
  ('32ab13c6-8a7a-551b-9250-236b0afa1625', '1c341258-dd12-5c37-920a-0dd187a63de3', '25 وردة بيبي روز', 'تنسيق كلاسيكي أنيق.', 15000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 1),
  ('5fde3335-3fe5-59c9-a1e1-36ec464d18e6', '1c341258-dd12-5c37-920a-0dd187a63de3', '50 وردة بيبي روز', 'باقة متوسطة مميزة.', 25000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 2),
  ('97f7578a-05c2-5912-97ff-ea2f082c3bee', '1c341258-dd12-5c37-920a-0dd187a63de3', '75 وردة بيبي روز', 'باقة كبيرة فاخرة.', 35000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 3),
  ('a67ec133-076e-5ae9-9201-6adc2c84b060', '1c341258-dd12-5c37-920a-0dd187a63de3', '100 وردة بيبي روز', 'باقة ملكية مميزة جداً.', 45000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 4),
  ('088128cf-59a7-5532-99fd-cd2a0ce59c44', '1c341258-dd12-5c37-920a-0dd187a63de3', '150 وردة بيبي روز', 'أضخم باقة بيبي روز + إكسسوارات مجاناً.', 65000, null, 'IQD', 'سعر تقديري.', false, null, null, 'كتالوج ورد بغداد للزهور الطبيعية.pdf', true, 5),
  ('9a85c6d5-236b-5d76-acac-b6381435e423', 'e879b3cf-dee2-55f8-aafe-9215c0bb2a66', 'العرض الأول', '100 طبق طعام + 100 علبة ببسي.', 990000, null, 'IQD', null, true, null, null, 'عروض قاعة الماس للمناسبات.pdf', true, 0),
  ('292943cd-3ab0-5589-8dd9-c02045d986f3', 'e879b3cf-dee2-55f8-aafe-9215c0bb2a66', 'العرض الثاني', '100 سندويج + 100 قطعة كيك + 200 علبة ببسي.', 990000, null, 'IQD', null, true, null, null, 'عروض قاعة الماس للمناسبات.pdf', true, 1),
  ('a56ef178-d24d-550c-bbcf-9a7deb3c7fad', 'e879b3cf-dee2-55f8-aafe-9215c0bb2a66', 'العرض الثالث', 'عرض بدون طعام (يشمل جميع الخدمات العامة).', 750000, null, 'IQD', null, true, null, null, 'عروض قاعة الماس للمناسبات.pdf', true, 2),
  ('ac010cb1-8ab1-5b91-afcd-e3294e7ac148', '3aaf0cb8-f58d-5cb0-9bf7-431b00f8ae87', 'العرض الشامل', 'تفاصيل العرض الأساسي + التصوير والتغطية السينمائية + هدايا مجانية (خدمة سحب الموبايلات، أرضية خاصة بمركز العرسان، ميز مهر، ميز حنة، عروض العصا الضوئية، الثريا الراقصة، شاشة هولوغرام، مسدسات دخان وشعلات، منظمة حفل، بروفات).', 5500000, null, 'IQD', null, true, null, null, 'عرض قاعة قصر روتانا.pdf', true, 0);
